1	using System.Diagnostics;
2	// 訂單取消＋通知的薄 HTTP API。程序內記憶體儲存（不保證重啟持久性）；每 request 一行 logs.jsonl；/metrics 文字格式。
3	// 通知走 Channel → NotificationWorker → POST 到 fake sink（OC_SINK_URL）。故障注入由 OC_FAULTS 指定的 JSON 檔提供，只供演練。
4	using System.Text.Json;
5	using System.Text.Json.Nodes;
6	using System.Threading.Channels;
7	using OrderCancel.Domain;
8	
9	var builder = WebApplication.CreateBuilder(args);
10	builder.Logging.ClearProviders();
11	Obs.Configure(builder);
12	var runDir = Environment.GetEnvironmentVariable("OC_RUN_DIR") ?? "runs/default";
13	Directory.CreateDirectory(runDir);
14	var versionFile = Path.Combine(AppContext.BaseDirectory, "VERSION");
15	var version = File.Exists(versionFile) ? File.ReadAllText(versionFile).Trim() : (Environment.GetEnvironmentVariable("OC_VERSION") ?? "unknown");
16	var faults = Faults.Load(Environment.GetEnvironmentVariable("OC_FAULTS"));
17	long gcTick = 0;
18	var store = new OrderStore();
19	var metrics = new Metrics();
20	var log = new JsonlLog(Path.Combine(runDir, "logs.jsonl"), version);
21	var channel = Channel.CreateUnbounded<Notification>();
22	builder.Services.AddSingleton(store); builder.Services.AddSingleton(metrics); builder.Services.AddSingleton(log); builder.Services.AddSingleton(faults);
23	builder.Services.AddSingleton(channel);
24	builder.Services.AddHostedService<NotificationWorker>();
25	var app = builder.Build();
26	Obs.Init(app);
27	// 例外中介層：任何未處理例外寫一行 log（型別、訊息、request_id）並回 500；OOM 這類也會留在 logs.jsonl 與 stderr。
28	app.Use(async (ctx, next) =>
29	{
30	    try { await next(); }
31	    catch (Exception ex)
32	    {
33	        var rid = ctx.Request.Headers["X-Request-Id"].FirstOrDefault();
34	        try { log.Write(new { level = "ERROR", @event = "unhandled_exception", request_id = rid, path = ctx.Request.Path.Value, exception = ex.GetType().FullName, message = ex.Message }); } catch { }
35	        try { Console.Error.WriteLine($"[unhandled] {ex.GetType().FullName}: {ex.Message} path={ctx.Request.Path} request_id={rid}"); } catch { }
36	        if (!ctx.Response.HasStarted) { ctx.Response.StatusCode = 500; await ctx.Response.WriteAsync("{\"ok\":false,\"reason\":\"internal_error\"}"); }
37	    }
38	});
39	log.Write(new { level = "INFO", @event = "startup", sink = Environment.GetEnvironmentVariable("OC_SINK_URL") });
40	
41	app.MapGet("/health", () => Results.Ok(new { ok = true, version }));
42	app.MapGet("/ready", () => Results.Ok(new { ready = true, version }));   // 記憶體儲存無外部依賴；readiness＝程序起來
43	app.MapPost("/orders", async (HttpRequest req) =>
44	{   // 建單（測試用）：body {id, shipped, paid}
45	    using var doc = await JsonDocument.ParseAsync(req.Body); var r = doc.RootElement;
46	    var id = r.GetProperty("id").GetString()!;
47	    var order = new Order(r.TryGetProperty("shipped", out var s) && s.GetBoolean(), r.TryGetProperty("paid", out var p) && p.GetBoolean(), false);
48	    store.Put(id, order);
49	    return Results.Ok(new { id, order });
50	});
51	app.MapGet("/orders/{id}", (string id) => store.TryGet(id, out var o) ? Results.Ok(new { id, order = o }) : Results.NotFound());
52	app.MapPost("/orders/{id}/cancel", async (string id, HttpRequest req) =>
53	{
54	    var t0 = DateTime.UtcNow;
55	    string? payload = null;
56	    if (req.ContentLength > 0) { using var sr = new StreamReader(req.Body); payload = await sr.ReadToEndAsync(); }
57	    if (faults.RetainPayloads) Retained.Keep(id, payload);   // 演練注入：把每筆 request body 留在記憶體，無上限
58	    var rid = req.Headers["X-Request-Id"].FirstOrDefault() ?? Guid.NewGuid().ToString("N")[..12];
59	    var runId = req.Headers["X-Run-Id"].FirstOrDefault();
60	    var actor = req.Headers["X-Actor"].FirstOrDefault();
61	    if (string.IsNullOrEmpty(actor))
62	    {
63	        metrics.Inc("cancel_requests_total", "unauthorized");
64	        log.Write(new { level = "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, result = "unauthorized" });
65	        return Results.Json(new { ok = false, reason = "unauthorized", request_id = rid }, statusCode: 401);
66	    }
67	    if (!store.TryGet(id, out var before))
68	    {
69	        metrics.Inc("cancel_requests_total", "not_found");
70	        log.Write(new { level = "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, result = "not_found" });
71	        return Results.Json(new { ok = false, reason = "not_found", request_id = rid }, statusCode: 404);
72	    }
73	    if (faults.FailPaidCancel && before.Paid && !before.Shipped && !before.Cancelled)
74	    {
75	        metrics.Inc("cancel_requests_total", "error");
76	        metrics.ObserveLatency((DateTime.UtcNow - t0).TotalMilliseconds);
77	        log.Write(new { level = "ERROR", @event = "cancel", request_id = rid, run_id = runId, order_id = id, actor, result = "error", error = "upstream_timeout" });
78	        return Results.Json(new { ok = false, reason = "upstream_timeout", request_id = rid }, statusCode: 503);
79	    }
80	    if (faults.CpuSpinMs > 0) { var sw = System.Diagnostics.Stopwatch.StartNew(); double x = 0; while (sw.ElapsedMilliseconds < faults.CpuSpinMs) x += Math.Sqrt(x + 1); }
81	    if (faults.GcEvery > 0 && Interlocked.Increment(ref gcTick) % faults.GcEvery == 0) GC.Collect(2, GCCollectionMode.Forced, true, true);
82	    var result = Cancellation.Cancel(before);
83	    bool transitioned = Cancellation.Transitioned(before, result);
84	    string outcome; int status;
85	    if (before.Shipped) { outcome = "rejected_shipped"; status = 409; }          // BR-02，不通知（NC-03）
86	    else if (transitioned)
87	    {
88	        outcome = "ok"; status = 200;
89	        if (!(faults.SkipPersistPct > 0 && Random.Shared.Next(100) < faults.SkipPersistPct)) store.Put(id, result.Order);
90	    }
91	    else { outcome = "idempotent"; status = 200; }                               // BR-04／NC-02，不通知
92	    metrics.Inc("cancel_requests_total", outcome);
93	    if (transitioned)
94	    {
95	        metrics.Inc("transitions_total");
96	        var n = new Notification(Guid.NewGuid().ToString("N"), id, rid, runId, "order_cancelled", result.RefundRequested);
97	        metrics.Inc("notify_enqueued_total");
98	        log.Write(new { @event="notify_enqueued", notification_id=n.NotificationId, request_id=rid, run_id=runId, order_id=id });
99	        if (faults.SyncNotify)
100	            await NotificationWorker.SendOnce(n, metrics, log, Environment.GetEnvironmentVariable("OC_SINK_URL") ?? "http://127.0.0.1:5081/notify");   // 演練注入：在請求路徑上同步等接收端
101	        else
102	            await channel.Writer.WriteAsync(n);
103	    }
104	    var lat = (DateTime.UtcNow - t0).TotalMilliseconds;
105	    metrics.ObserveLatency(lat);
106	    log.Write(new { level = status == 200 ? "INFO" : "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, actor, result = outcome, transitioned, refund_requested = result.RefundRequested, latency_ms = Math.Round(lat, 1), queue_depth = channel.Reader.Count });
107	    return Results.Json(new { ok = status == 200, transitioned, refund_requested = result.RefundRequested, reason = status == 200 ? null : outcome, request_id = rid, order = status == 200 ? result.Order : before }, statusCode: status);
108	});
109	var startedAt = DateTime.UtcNow; string? frozen = null;
110	app.MapGet("/metrics", () =>
111	{
112	    var text = metrics.Render(channel.Reader.Count, version);
113	    if (faults.MetricsFreezeAfterS > 0 && (DateTime.UtcNow - startedAt).TotalSeconds > faults.MetricsFreezeAfterS) text = frozen ??= text;
114	    return Results.Text(text, "text/plain");
115	});
116	app.Run();
117	
118	record Notification(string NotificationId, string OrderId, string RequestId, string? RunId, string Kind, bool RefundRequested, int Deferrals = 0) { public ActivityContext Parent {get;init;} = Activity.Current?.Context ?? default; public long QueuedAt {get;init;} = Stopwatch.GetTimestamp(); }
119	
120	sealed class OrderStore
121	{
122	    readonly Dictionary<string, Order> _d = new(); readonly object _g = new();
123	    public static int HoldMs;
124	    public void Put(string id, Order o) { lock (_g) { _d[id] = o; if (HoldMs > 0) Thread.Sleep(HoldMs); } }
125	    public bool TryGet(string id, out Order o) { lock (_g) return _d.TryGetValue(id, out o!); }
126	}
127	
128	sealed class Metrics
129	{
130	    readonly Dictionary<string, long> _c = new(); readonly object _g = new();
131	    public void Inc(string name, string? label = null)
132	    {
133	        var k = label is null ? name : name + "{result=\"" + label + "\"}";
134	        lock (_g) _c[k] = _c.GetValueOrDefault(k) + 1;
135	    }
136	    static readonly double[] Buckets = { 5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000 };
137	    readonly long[] _hist = new long[Buckets.Length + 1]; double _latSum; long _latCount;
138	    public void ObserveLatency(double ms)
139	    {
140	        lock (_g) { _latSum += ms; _latCount++; int i = 0; while (i < Buckets.Length && ms > Buckets[i]) i++; _hist[i]++; }
141	    }
142	    public string Render(int depth, string version)
143	    {
144	        lock (_g)
145	        {
146	            var sb = new System.Text.StringBuilder();
147	            foreach (var kv in _c.OrderBy(k => k.Key)) sb.Append("oc_").Append(kv.Key).Append(' ').Append(kv.Value).Append('\n');
148	            sb.Append("oc_notify_queue_depth ").Append(depth).Append('\n');
149	            long cum = 0;
150	            for (int i = 0; i < Buckets.Length; i++) { cum += _hist[i]; sb.Append("oc_request_latency_ms_bucket{le=\"").Append(Buckets[i]).Append("\"} ").Append(cum).Append('\n'); }
151	            cum += _hist[Buckets.Length]; sb.Append("oc_request_latency_ms_bucket{le=\"+Inf\"} ").Append(cum).Append('\n');
152	            sb.Append("oc_request_latency_ms_sum ").Append(Math.Round(_latSum, 1)).Append('\n').Append("oc_request_latency_ms_count ").Append(_latCount).Append('\n');
153	            sb.Append("oc_gc_heap_bytes ").Append(GC.GetTotalMemory(false)).Append('\n');
154	            sb.Append("oc_working_set_bytes ").Append(Environment.WorkingSet).Append('\n');
155	            sb.Append("oc_gc_collections_gen2 ").Append(GC.CollectionCount(2)).Append('\n');
156	            sb.Append("oc_gc_pause_seconds_total ").Append(Math.Round(GC.GetTotalPauseDuration().TotalSeconds, 3)).Append('\n');
157	            sb.Append("oc_process_cpu_seconds_total ").Append(Math.Round(System.Diagnostics.Process.GetCurrentProcess().TotalProcessorTime.TotalSeconds, 2)).Append('\n');
158	            sb.Append("oc_info{version=\"").Append(version).Append("\"} 1\n");
159	            return sb.ToString();
160	        }
161	    }
162	}
