164	sealed class JsonlLog
165	{
166	    readonly string _p; readonly string _v; readonly object _g = new();
167	    public JsonlLog(string p, string v) { _p = p; _v = v; }
168	    public void Write(object o)
169	    {
170	        var d = JsonSerializer.SerializeToNode(o)!.AsObject();
171	        d["ts"] = DateTimeOffset.Now.ToString("o"); d["version"] = _v;
172	        d["trace_id"]=Activity.Current?.TraceId.ToString(); d["span_id"]=Activity.Current?.SpanId.ToString();
173	        Obs.Log(d.ToJsonString());
174	        lock (_g) File.AppendAllText(_p, d.ToJsonString() + "\n");
175	    }
176	}
