178	// 演練注入 retain_payloads 的落點（v1.2.0 修復後）：客服查詢暫存改為有上限的環狀緩衝——最多 MaxItems 筆、每筆只留前 MaxBodyChars 字與原長度。
179	// v1.1.0 之前是無上限的 List，壓力下把 heap 撐到上限（見 evidence/runs/oom-retained-payloads-*、diagnosis/oom）。
180	static class Retained
181	{
182	    const int MaxItems = 256, MaxBodyChars = 256;
183	    static readonly Queue<(string OrderId, string Head, int Length)> _items = new(); static readonly object _g = new();
184	    // 演練用回歸開關 regress_unbounded_retain：重現 v1.1.0 修復前的行為（無上限、保留完整 body）。預設關閉。
185	    public static bool RegressUnbounded;
186	    static readonly List<(string OrderId, string Body)> _unbounded = new();
187	    public static void Keep(string orderId, string? body)
188	    {
189	        var b = body ?? "";
190	        if (RegressUnbounded) { lock (_g) _unbounded.Add((orderId, b)); return; }
191	        lock (_g) { _items.Enqueue((orderId, b.Length > MaxBodyChars ? b[..MaxBodyChars] : b, b.Length)); while (_items.Count > MaxItems) _items.Dequeue(); }
192	    }
193	    public static int Count { get { lock (_g) return RegressUnbounded ? _unbounded.Count : _items.Count; } }
194	}
195	
196	sealed class Faults
197	{
198	    public int? DropOverQueue; public int DelayMs; public bool RetainPayloads; public bool SyncNotify;
199	    // 演練用回歸開關（預設關閉）：重現已修復 bug 被改回去的情境，供後續盲查。
200	    public bool RegressUnboundedRetain; public bool RegressDeferredDrop;
201	    // 演練注入，夜間巡查用（預設關閉）：專打可觀測性盲點。
202	    // 演練注入 metrics_freeze_after_s：啟動 N 秒後 /metrics 回傳凍結的快照（up 仍為 1，counter 不再前進，看起來很平靜）。
203	    // 演練注入 fail_paid_cancel：已付款未出貨的取消一律 503（只壞一小群，總錯誤率被稀釋）。
204	    // 演練注入 skip_persist_pct：成功取消中有 N% 回 200 並發通知，但沒有寫回訂單狀態（回應與業務結果不一致）。
205	    public int MetricsFreezeAfterS; public bool FailPaidCancel; public int SkipPersistPct;
206	    // 演練注入 sink_url_override：接收端網址設錯（設定錯誤類）。cpu_spin_ms：每筆取消空轉 N ms（CPU 飽和）。
207	    // 演練注入 lock_hold_ms：寫入訂單時持鎖 N ms（鎖競爭）。gc_every：每 N 筆取消強制完整 GC（GC 暫停）。
208	    public bool SinkUnreachable; public int CpuSpinMs; public int LockHoldMs; public int GcEvery;
209	    public bool Any => DropOverQueue is not null || DelayMs > 0 || RetainPayloads || SyncNotify || RegressUnboundedRetain || RegressDeferredDrop
210	                       || MetricsFreezeAfterS > 0 || FailPaidCancel || SkipPersistPct > 0 || SinkUnreachable || CpuSpinMs > 0 || LockHoldMs > 0 || GcEvery > 0;
211	    public static Faults Load(string? path)
212	    {
213	        var f = new Faults();
214	        if (string.IsNullOrEmpty(path) || !File.Exists(path)) return f;
215	        using var doc = JsonDocument.Parse(File.ReadAllText(path)); var r = doc.RootElement;
216	        if (r.TryGetProperty("notify_drop_over_queue", out var q)) f.DropOverQueue = q.GetInt32();
217	        if (r.TryGetProperty("notify_delay_ms", out var d)) f.DelayMs = d.GetInt32();
218	        if (r.TryGetProperty("retain_payloads", out var rp)) f.RetainPayloads = rp.GetBoolean();
219	        if (r.TryGetProperty("sync_notify", out var sn)) f.SyncNotify = sn.GetBoolean();
220	        if (r.TryGetProperty("regress_unbounded_retain", out var ru)) f.RegressUnboundedRetain = ru.GetBoolean();
221	        if (r.TryGetProperty("regress_deferred_drop", out var rd)) f.RegressDeferredDrop = rd.GetBoolean();
222	        if (r.TryGetProperty("metrics_freeze_after_s", out var mf)) f.MetricsFreezeAfterS = mf.GetInt32();
223	        if (r.TryGetProperty("fail_paid_cancel", out var fp)) f.FailPaidCancel = fp.GetBoolean();
224	        if (r.TryGetProperty("skip_persist_pct", out var sp)) f.SkipPersistPct = sp.GetInt32();
225	        if (r.TryGetProperty("cpu_spin_ms", out var cs)) f.CpuSpinMs = cs.GetInt32();
226	        if (r.TryGetProperty("lock_hold_ms", out var lh)) f.LockHoldMs = lh.GetInt32();
227	        if (r.TryGetProperty("gc_every", out var ge)) f.GcEvery = ge.GetInt32();
228	        if (r.TryGetProperty("sink_url_override", out var so)) { f.SinkUnreachable = true; Environment.SetEnvironmentVariable("OC_SINK_URL", so.GetString()); }
229	        OrderStore.HoldMs = f.LockHoldMs;
230	        Retained.RegressUnbounded = f.RegressUnboundedRetain;
231	        return f;
232	    }
233	}
