235	// 通知 worker：從 channel 取出 → POST sink → 失敗重試 3 次（200／400／800 ms）→ 超過進 dead_letter（NC-05）。
236	// 故障 notify_drop_over_queue（演練用）：佇列深度超過 N 時觸發「壓力延後」路徑。
237	// v1.0.0 的行為是記一行 notify_deferred 後不再重送、sent 計數照加（服務說送了、接收端沒收據）；v1.1.0 改為重排到隊尾、sent 只在 ack 後才加。
238	// 這條故障設計移植自 O 服務 fault-A；是演練用注入，不是自然事故。
239	sealed class NotificationWorker : BackgroundService
240	{
241	    readonly Channel<Notification> _ch; readonly Metrics _m; readonly JsonlLog _log; readonly Faults _f; readonly HttpClient _http = new();
242	    readonly string _sink = Environment.GetEnvironmentVariable("OC_SINK_URL") ?? "http://127.0.0.1:5081/notify";
243	    static readonly int[] Backoff = { 200, 400, 800 };
244	    const int MaxDeferrals = 5;
245	    public NotificationWorker(Channel<Notification> ch, Metrics m, JsonlLog log, Faults f) { _ch = ch; _m = m; _log = log; _f = f; }
246	    static readonly HttpClient SharedHttp = new();
247	    /// 同步送一次（含重試），供 sync_notify 演練路徑使用；計數規則與 worker 相同。
248	    public static async Task SendOnce(Notification n, Metrics m, JsonlLog log, string sink)
249	    {
250	        bool sent = false;
251	        for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
252	        {
253	            try
254	            {
255	                var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
256	                var resp = await SharedHttp.PostAsync(sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"));
257	                sent = resp.IsSuccessStatusCode;
258	            }
259	            catch (Exception e) { log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name }); }
260	            if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt]);
261	        }
262	        if (sent) { m.Inc("notify_sent_total"); log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, sync = true }); }
263	        else { m.Inc("notify_failed_total"); m.Inc("notify_dead_letter_total"); log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 }); }
264	    }
265	    protected override async Task ExecuteAsync(CancellationToken ct)
266	    {
267	        await foreach (var n in _ch.Reader.ReadAllAsync(ct))
268	        {
269	            using var span=Obs.Source.StartActivity("notification.process",ActivityKind.Consumer,n.Parent);
270	            var wait=Stopwatch.GetElapsedTime(n.QueuedAt).TotalMilliseconds;
271	            span?.SetTag("notification.id",n.NotificationId);span?.SetTag("run.id",n.RunId);
272	            span?.SetTag("queue.wait_ms",wait);Obs.QueueWait.Record(wait);
273	            _log.Write(new { @event="notify_worker_start",notification_id=n.NotificationId,request_id=n.RequestId,run_id=n.RunId,queue_wait_ms=wait,deferrals=n.Deferrals });
274	
275	            if (_f.DelayMs > 0) await Task.Delay(_f.DelayMs, ct);
276	            if (_f.DropOverQueue is int q0 && _ch.Reader.Count > q0 && _f.RegressDeferredDrop)
277	            {   // 演練用回歸開關 regress_deferred_drop：重現 v1.0.0 修復前的行為——記一行 notify_deferred 就不再重送，sent 照加。
278	                _m.Inc("notify_sent_total");
279	                _log.Write(new { level = "INFO", @event = "notify_deferred", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, queue_depth = _ch.Reader.Count });
280	                continue;
281	            }
282	            if (_f.DropOverQueue is int q && _ch.Reader.Count > q)
283	            {   // v1.1.0 修復：壓力下不再「假裝送了」。延後＝重排到隊尾（最多 MaxDeferrals 次），sent_total 只在接收端 ack 後才加；延後另計。
284	                if (n.Deferrals < MaxDeferrals)
285	                {
286	                    _m.Inc("notify_deferred_total");
287	                    _log.Write(new { level = "INFO", @event = "notify_deferred", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, queue_depth = _ch.Reader.Count, deferrals = n.Deferrals + 1, requeued = true });
288	                    await _ch.Writer.WriteAsync(n with { Deferrals = n.Deferrals + 1 }, ct);
289	                    continue;
290	                }
291	                _log.Write(new { level = "WARN", @event = "notify_deferral_limit", notification_id = n.NotificationId, deferrals = n.Deferrals, note = "超過延後上限，改走一般送出／重試路徑" });
292	            }
293	            bool sent = false;
294	            for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
295	            {
296	                try
297	                {
298	                    var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
299	                    var resp = await _http.PostAsync(_sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"), ct);
300	                    sent = resp.IsSuccessStatusCode;
301	                    if (!sent) _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, status = (int)resp.StatusCode });
302	                }
303	                catch (Exception e) when (!ct.IsCancellationRequested)
304	                {
305	                    _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name });
306	                }
307	                if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt], ct);
308	            }
309	            if (sent)
310	            {
311	                _m.Inc("notify_sent_total");
312	                _log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId });
313	            }
314	            else
315	            {
