2	using System.Diagnostics;
3	using System.Diagnostics.Metrics;
4	using OpenTelemetry;
5	using OpenTelemetry.Resources;
6	using OpenTelemetry.Trace;
7	using OpenTelemetry.Metrics;
8	using OpenTelemetry.Logs;
9	public static class Obs {
10	 public static readonly ActivitySource Source=new("Day24.Notifications");
11	 public static readonly Meter Meter=new("Day24.Notifications");
12	 public static readonly Histogram<double> QueueWait=Meter.CreateHistogram<double>("notification.queue.wait","ms");
13	 static ILogger? logger;
14	 public static void Configure(WebApplicationBuilder b) {
15	  var name=Environment.GetEnvironmentVariable("OTEL_SERVICE_NAME") ?? "day24-api";
16	  b.Services.AddOpenTelemetry().ConfigureResource(r=>r.AddService(name).AddAttributes(new Dictionary<string,object>{{"lab.variant","after"}}))
